import jsonschema

problems = []
try:
    jsonschema.validate(definition, command_contract())
except jsonschema.ValidationError as error:
    problems.append("contract: " + error.message)
    return problems

trust = definition["trust_level"]
caps = definition.get("required_capabilities", [])

# An untrusted command runs in a container with no egress and no credential
# lease. Declaring a capability it can never be given is a definition bug,
# and saying so here is better than a confusing failure at 03:00.
if trust == "untrusted" and caps:
    problems.append(
        "untrusted commands run without %s; promote to verified after review"
        % ", ".join(caps)
    )
if trust == "untrusted" and definition.get("auth"):
    problems.append("untrusted commands never receive a credential lease")

if definition["effect"] == "mutating" and not definition.get("dry_run_example"):
    problems.append(
        "a mutating command needs a dry_run_example, or dry run cannot be honest"
    )
if definition["risk_level"] == "high" and definition["effect"] != "mutating":
    problems.append("a high-risk command that changes nothing is mis-classified")
if definition["kind"] == "shell" and trust != "trusted":
    problems.append("shell commands are platform-provided only")
if not definition["output_schema"].get("properties"):
    problems.append("output_schema must describe real fields; playbooks type-check against it")
return problems

